  while ((m = vkRx.exec(raw)) !== null) {
    const h = m[1].toLowerCase();
    if (/^(away|share|widget|search|feed|im|id0)$/.test(h)) { rejected.push({ raw: m[0], platform: 'vk', reason: 'not_a_public_community' }); continue; }
    add(vk, 'vk.com/' + h);
