    urls: (allow.indexOf('website') >= 0) ? ex.websites : [],
    telegram_channels: (allow.indexOf('telegram') >= 0) ? ex.telegram_channels : [],
    vk_communities: (allow.indexOf('vk') >= 0) ? ex.vk_sources : [],
