  return [
    'План запроса (подтвердите перед запуском):',
    '• Интент: ' + str(plan.intent),
    '• Ниша/услуга: ' + str(plan.niche),
    '• Регион: ' + str(plan.region),
    '• Источники: ' + (plan.sources || []).join(', '),
    '• Лимит элементов/источник: ' + num(plan.max_items, 0),
